package com.yourplugin.securescreen;
import android.app.Activity;import android.graphics.Color;import android.view.View;import android.view.WindowManager;import android.widget.FrameLayout;import org.apache.cordova.*;import org.json.JSONArray;
public class SecureScreen extends CordovaPlugin {private View overlayView;private boolean blurEnabled=false;@Override public boolean execute(String action, JSONArray args, CallbackContext cb){Activity a=cordova.getActivity();switch(action){case "enableScreenshotProtection":a.runOnUiThread(() -> a.getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE));cb.success();return true;case "disableScreenshotProtection":a.runOnUiThread(() -> a.getWindow().clearFlags(WindowManager.LayoutParams.FLAG_SECURE));cb.success();return true;case "enableAppSwitcherBlur":blurEnabled=true;createOverlay(a);cb.success();return true;case "disableAppSwitcherBlur":blurEnabled=false;removeOverlay();cb.success();return true;}return false;}private void createOverlay(Activity a){if(overlayView!=null)return;overlayView=new View(a);overlayView.setBackgroundColor(Color.WHITE);a.addContentView(overlayView,new FrameLayout.LayoutParams(FrameLayout.LayoutParams.MATCH_PARENT,FrameLayout.LayoutParams.MATCH_PARENT));overlayView.setVisibility(View.GONE);}private void removeOverlay(){if(overlayView!=null&&overlayView.getParent() instanceof FrameLayout){((FrameLayout)overlayView.getParent()).removeView(overlayView);overlayView=null;}}@Override public void onPause(boolean multitasking){if(blurEnabled&&overlayView!=null)overlayView.setVisibility(View.VISIBLE);}@Override public void onResume(boolean multitasking){if(overlayView!=null)overlayView.setVisibility(View.GONE);}}